import numpy as np,json
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from PIL import Image
from rcb_client import Robot
S=json.load(open('/app/output/spec.json'))
RANGE=np.array(S['qpos']['range']); AXIS=np.array(S['proprio']['axis']); POS=np.array(S['proprio']['position_m'])
BASE=np.zeros(19); BASE[[2,7]]=-.4; BASE[[3,8]]=.8; BASE[[4,9]]=-.4

def action(q):return np.clip(2*(np.array(q)-RANGE[:,0])/(RANGE[:,1]-RANGE[:,0])-1,-1,1)
def trans(q,ids):
 T=np.eye(4)
 for j in ids:
  r=Rotation.from_rotvec(AXIS[j]*q[j]).as_matrix(); t=np.eye(4);t[:3,:3]=r;t[:3,3]=POS[j]-r@POS[j];T=T@t
 return T

def hand(q,left=True):
 ids=[10]+list(range(11,15) if left else range(15,19)); p=np.array([.329,.214 if left else -.214,.097,1]);return (trans(q,ids)@p)[:3]
def ik(p,left=True,seed=None):
 ids=list(range(11,15) if left else range(15,19)); q=BASE.copy()
 def fun(v):
  q[ids]=v;return np.r_[10*(hand(q,left)-p),.015*v]
 o=least_squares(fun,np.zeros(4) if seed is None else seed,bounds=(RANGE[ids,0]+.001,RANGE[ids,1]-.001),max_nfev=300)
 return o.x,hand(np.concatenate([q[:ids[0]],o.x,q[ids[-1]+1:]]),left)

def save(o,prefix):
 for k,v in o.get('images',{}).items():Image.fromarray(v).save('/app/output/'+prefix+'_'+k+'.png')
 print(prefix, {k:v for k,v in o.items() if k not in ['images','depth']})
if __name__=='__main__':
 for p in [[.4,.11,.35],[.4,.11,.1],[.4,.11,.5]]:print('IK',p,ik(p))
 r=Robot();o=r.step('qpos',[action(BASE)]*5);save(o,'s5')
PY
