from control import *
def rot(o):return Rotation.align_vectors([[0,0,1]],[-np.array(o['imu']['gravity'])])[0].as_matrix()
def linkpoint(q,i,p):
 if i==0:ids=[]
 elif i<=5:ids=range(i)
 elif i<=10:ids=range(5,i)
 elif i==11:ids=[10]
 elif i<=16:ids=[10]+list(range(11,min(15,i)))
 else:ids=[10]+list(range(15,min(19,i-4)))
 return (trans(q,ids)@np.r_[p,1])[:3]
def com(q):
 masses=S['links']['mass_kg'];pts=[linkpoint(q,i,p) for i,p in enumerate(S['links']['com_m'])];return np.average(pts,axis=0,weights=masses)
class Balance:
 def __init__(self,o):
  q=np.array(o['proprio']['joint_pos']);R=rot(o);self.anchors=[R@linkpoint(q,i,S['links']['com_m'][i]) for i in [5,10]];self.c0=(R@com(q))[0];self.last=self.c0;self.vel=0
 def update(self,o,q):
  actual=np.array(o['proprio']['joint_pos']);R=rot(o);root=np.mean([self.anchors[k]-R@linkpoint(actual,i,S['links']['com_m'][i]) for k,i in enumerate([5,10])],axis=0);c=(root+R@com(actual))[0];self.vel=.8*self.vel+.2*(c-self.last)/.02;self.last=c
  desired=np.clip(2.0*(self.c0-c)-.5*self.vel,-.3,.3);g=o['imu']['gravity'];w=o['imu']['gyro'];error=g[0]-desired
  q[[2,7]]=-.4+.9*error+.15*w[1];q[[4,9]]=-.4+1.1*error+.12*w[1];q[[1,6]]=-.4*g[1]+.1*w[0]
  return q,(c,self.vel,desired)
PY
