from control import *
from scipy.ndimage import label,binary_fill_holes

def sphere(images):
 origins=[];rays=[];f=128/np.tan(np.pi/8)
 for name,cy in [('left_eye_camera',.03),('right_eye_camera',-.03)]:
  im=images[name];m=(im[:,:,0]>70)&(im[:,:,0]>im[:,:,1]*1.2)&(im[:,:,1]>im[:,:,2]*1.2);lab,n=label(m);counts=np.bincount(lab.ravel());counts[0]=0
  if len(counts)<2 or max(counts)<30:continue
  mask=binary_fill_holes(lab==counts.argmax());pts=set()
  for x in range(1,255,2):
   yy=np.where(mask[:,x])[0]
   if len(yy)>0 and 1<yy.min()<254:pts.add((x,int(yy.min())-.5))
   if len(yy)>0 and 1<yy.max()<254:pts.add((x,int(yy.max())+.5))
  for y in range(1,255,2):
   xx=np.where(mask[y,:])[0]
   if len(xx)>0 and 1<xx.min()<254:pts.add((float(xx.min())-.5,y))
   if len(xx)>0 and 1<xx.max()<254:pts.add((float(xx.max())+.5,y))
  for x,y in pts:
   ray=np.array([1,-(x-127.5)/f,-(y-127.5)/f]);ray/=np.linalg.norm(ray);rays.append(ray);origins.append([.1,cy,.65])
 if len(rays)<12:return None
 rays=np.array(rays);origins=np.array(origins)
 def fun(v):
  rel=v[:3]-origins;return (np.linalg.norm(np.cross(rel,rays),axis=1)-v[3])
 opt=least_squares(fun,[.24,0,.5,.1],bounds=([.101,-1,-.5,.01],[3,1,2,.4]),loss='soft_l1',f_scale=.0005,max_nfev=300)
 return opt.x,np.std(fun(opt.x)),len(rays)
if __name__=='__main__':
 for fn in ['p95','p110','f115','b75']:
  ims={name:np.array(Image.open('/app/output/'+fn+'_'+name+'.png')) for name in ['left_eye_camera','right_eye_camera']};print(fn,sphere(ims))
